def tree(src,dst):
    assert src.is_dir() and not dst.exists()
    dst.mkdir(parents=True)
    for p in sorted(src.rglob("*")):
        assert not p.is_symlink()
        if p.is_file(): copy_file(p,dst/p.relative_to(src))
